  "response_type": "answer",
  "answer": "If you submit an approved expense report only three business days before payroll close, the reimbursement will be processed in the following payroll cycle, not the next regular payroll cycle.",
  "citations": [
    {
      "document_id": "FIN-001",
      "document_title": "Expense, Procurement, and Reimbursement Policy",
      "section_heading": "Reimbursement Timing",
      "chunk_id": "08133959-8b36-4832-8e3a-9c76796459f3",
      "citation_text": "Approved expense reports are reimbursed in the next regular payroll cycle when submitted at least five business days before payroll close. Reports submitted after the cutoff move to the following payroll cycle."
    }
  ],
  "supported_claims": [
    "Expense reports submitted less than five business days before payroll close are reimbursed in the following payroll cycle."
  ],
  "unsupported_claims": [],
  "validation_notes": "The policy clearly states the cutoff is five business days before payroll close for reimbursement in the next payroll cycle."
}
